import { validateScene } from 'src/core';
import { officeScene } from '../OfficeNetworkLive/scene';
import { OFFICE_LIVE_SCENE } from '../OfficeNetworkLive/OfficeNetworkLive';

// The scene is generated by demos/office-network.demo.ts, and the example
// drives connections by the ids that script gives them.
describe('Office network, live', () => {
  it('loads a valid scene', () => {
    for (const scene of [officeScene, OFFICE_LIVE_SCENE]) {
      const result = validateScene(scene);
      expect(result.ok ? [] : result.errors).toEqual([]);
    }
  });

  it('has the connections the example drives', () => {
    const ids = new Set(
      (officeScene.connections ?? []).map((c) => {
        return c.id;
      })
    );
    const missing = [
      'fibre-ont--firewall',
      'cellular-router--firewall',
      'firewall--core-switch',
      'firewall--poe-switch',
      'core-switch--poe-switch',
      'laptop--ap-rear',
      'ap-rear--poe-switch',
      'nas--core-switch',
      'ups--core-switch',
      'ups--firewall'
    ].filter((id) => {
      return !ids.has(id);
    });
    expect(missing).toEqual([]);
  });
});
